# ==============================================================================# 023_SESSION_ENGINE.py# ==============================================================================import sqlite3import secretsfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS sessions(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    token TEXT,    username TEXT,    status TEXT)""")conn.commit()def create_session(username):    token = secrets.token_hex(32)    cur.execute(        """        INSERT INTO sessions(            created_at,            token,            username,            status        )        VALUES(?,?,?,?)        """,        (            datetime.now().isoformat(),            token,            username,            "ACTIVE"        )    )    conn.commit()    return tokentoken = create_session("admin")cur.execute("""SELECTid,username,statusFROM sessionsORDER BY id DESCLIMIT 1""")print("="*80)print("SESSION ENGINE")print("="*80)print(dict(cur.fetchone()))print()print("TOKEN")print(token)print("="*80)conn.close()

